-- Generated by backend/store/pgschema from the fully migrated combined
-- SQLite schema. Do not edit by hand: TestBaselineMatchesSQLiteSchema
-- regenerates this file and fails when it differs, which is what keeps the
-- PostgreSQL baseline honest while SQLite migrations still land.
--
-- Type choices are documented in translate.go. In short: unix timestamps and
-- 0/1 booleans stay bigint, and every text column is C-collated so ordering
-- and comparison keep the byte-wise semantics the store relies on.

-- table schema_migrations
CREATE TABLE schema_migrations (
  scope text COLLATE "C" NOT NULL,
  version text COLLATE "C" NOT NULL,
  applied_at bigint NOT NULL,
  checksum text COLLATE "C" NOT NULL,
  PRIMARY KEY(scope, version)
);

-- table users
CREATE TABLE users (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email text COLLATE "C" NOT NULL UNIQUE,
  name text COLLATE "C" NOT NULL,
  password_hash text COLLATE "C" NOT NULL,
  is_admin bigint NOT NULL DEFAULT 0,
  date_locale text COLLATE "C" NOT NULL DEFAULT '',
  date_format text COLLATE "C" NOT NULL DEFAULT 'mdy',
  theme text COLLATE "C" NOT NULL DEFAULT 'classic',
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  search_preset text COLLATE "C" NOT NULL DEFAULT 'balanced',
  search_recency_bias text COLLATE "C" NOT NULL DEFAULT 'normal',
  search_fuzzy text COLLATE "C" NOT NULL DEFAULT 'balanced',
  search_sender_boost bigint NOT NULL DEFAULT 1,
  search_attachment_weight text COLLATE "C" NOT NULL DEFAULT 'normal',
  search_compact_splitting bigint NOT NULL DEFAULT 1,
  search_sender_history text COLLATE "C" NOT NULL DEFAULT 'normal',
  search_contact_boost text COLLATE "C" NOT NULL DEFAULT 'normal',
  backup_email text COLLATE "C" NOT NULL DEFAULT ''
);

