  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  dispatched_at bigint NOT NULL DEFAULT 0,
  completed_at bigint NOT NULL DEFAULT 0,
  consumed_at bigint NOT NULL DEFAULT 0,
  expires_at bigint NOT NULL,
  dispatch_owner text COLLATE "C" NOT NULL DEFAULT '',
  dispatch_attempt bigint NOT NULL DEFAULT 0,
  dispatch_finished_at bigint NOT NULL DEFAULT 0,
  destination_snapshot_uid_validity bigint NOT NULL DEFAULT 0,
  destination_snapshot_uid_next bigint NOT NULL DEFAULT 0
